begin;
create table public.arena_alliance_chat_messages(id bigint generated always as identity primary key,alliance_id uuid not null references public.arena_alliances(id)on delete cascade,author_id uuid references public.profiles(id)on delete set null,body text not null check(length(trim(body))between 1 and 500),reply_to bigint references public.arena_alliance_chat_messages(id)on delete set null,deleted_at timestamptz,created_at timestamptz not null default now());create index arena_alliance_chat_recent on public.arena_alliance_chat_messages(alliance_id,id desc)where deleted_at is null;alter table public.arena_alliance_chat_messages enable row level security;alter table public.arena_alliance_chat_messages force row level security;revoke all on public.arena_alliance_chat_messages from anon,authenticated;grant select on public.arena_alliance_chat_messages to authenticated;
create policy arena_alliance_chat_realtime_read on public.arena_alliance_chat_messages for select to authenticated using(exists(select 1 from public.arena_alliance_members m where m.alliance_id=arena_alliance_chat_messages.alliance_id and m.user_id=(select auth.uid())));alter publication supabase_realtime add table public.arena_alliance_chat_messages;
create or replace function public.arena_get_alliance_chat(p_before_id bigint default null,p_limit integer default 40)returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;return(select coalesce(jsonb_agg(to_jsonb(x)order by id),'[]'::jsonb)from(select m.id,m.body,m.reply_to,m.author_id,m.created_at,coalesce(p.display_name,'Guardião')author_name from public.arena_alliance_chat_messages m left join public.profiles p on p.id=m.author_id where m.alliance_id=v_alliance and m.deleted_at is null and(p_before_id is null or m.id<p_before_id)order by m.id desc limit least(greatest(p_limit,1),80))x);end;$$;
create or replace function public.arena_send_alliance_chat(p_body text,p_reply_to bigint default null)returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_id bigint;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;if exists(select 1 from public.arena_alliance_chat_messages where author_id=v_user and created_at>now()-interval'2 seconds')then raise exception'rate limited';end if;if p_reply_to is not null and not exists(select 1 from public.arena_alliance_chat_messages where id=p_reply_to and alliance_id=v_alliance)then raise exception'invalid reply';end if;insert into public.arena_alliance_chat_messages(alliance_id,author_id,body,reply_to)values(v_alliance,v_user,trim(p_body),p_reply_to)returning id into v_id;return v_id;end;$$;
revoke all on function public.arena_get_alliance_chat(bigint,integer),public.arena_send_alliance_chat(text,bigint)from public;grant execute on function public.arena_get_alliance_chat(bigint,integer),public.arena_send_alliance_chat(text,bigint)to authenticated;commit;
